/*
Noble Diagnostic Centre - Mindray BC-5380 (BC5300DataBase)
Replace L-J QC File Nos 43-63 with pack values from the printed QCLJ charts.

Written for SQL Server 2005 (Mindray analyser). One INSERT per row.
No DECLARE @x = value. No multi-row VALUES lists.

Copy this file to a USB stick. Close the analyser software, then run
against BC5300DataBase:

  sqlcmd -S . -d BC5300DataBase -E -b -i NDC_BC5380_QCLJ_Files_43_63.sql

If the instance is named SQLEXPRESS:

  sqlcmd -S .\SQLEXPRESS -d BC5300DataBase -E -b -i NDC_BC5380_QCLJ_Files_43_63.sql

Or open in SQL Server Management Studio, set the database to
BC5300DataBase, and Execute (F5).

What this script does
  0. Copies the full live tables before touching anything:
       dbo.QcLjRecord   -> dbo.QcLjRecord_2026Bck
       dbo.QcLjRefLimit -> dbo.QcLjRefLimit_2026Bck
     If those _2026Bck tables already exist, they are left as-is.
  1. Deletes live QcLjRecord rows for File 43-63
  2. Updates QcLjRefLimit for File 43-60; inserts File 61-63 if missing
  3. Inserts 906 QC runs (File 43-63) from the printed pack
  4. Sets SampleID = ID on the new rows
  5. Rolls back the replace (not the _2026Bck copies) if counts do not match

Does not change printed File Nos. Does not touch files 1-42.
Instrument SN on new rows: RD-51100738. Operator: NOBLE. Setter: MU.
BloodMode 0 = CT-WB.

Expected after a successful run
  File 43 BC2507BL Low    47 rows  WBC Target 3.15  Upper 3.65  Lower 2.65
  Total records File 43-63 = 906

To revert, run the commented block at the bottom of this file.
*/

USE [BC5300DataBase];
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;

IF DB_NAME() <> N'BC5300DataBase'
BEGIN
    RAISERROR('Wrong database - expected BC5300DataBase', 16, 1);
    RETURN;
END

PRINT '--- full-table copies for revert: <table>_2026Bck ---';

IF OBJECT_ID(N'dbo.QcLjRecord_2026Bck', N'U') IS NULL
BEGIN
    SELECT * INTO dbo.QcLjRecord_2026Bck FROM dbo.QcLjRecord;
    PRINT 'Copied dbo.QcLjRecord -> dbo.QcLjRecord_2026Bck  rows=' + CONVERT(varchar(12), @@ROWCOUNT);
END
ELSE
    PRINT 'dbo.QcLjRecord_2026Bck already present - left unchanged';

IF OBJECT_ID(N'dbo.QcLjRefLimit_2026Bck', N'U') IS NULL
BEGIN
    SELECT * INTO dbo.QcLjRefLimit_2026Bck FROM dbo.QcLjRefLimit;
    PRINT 'Copied dbo.QcLjRefLimit -> dbo.QcLjRefLimit_2026Bck  rows=' + CONVERT(varchar(12), @@ROWCOUNT);
END
ELSE
    PRINT 'dbo.QcLjRefLimit_2026Bck already present - left unchanged';
GO

